import{z as l,x as s,o as r,c as p,q as t,j as i,D as B,d as a,s as n,S as o,b as e}from"./chunks/framework.C8m1ZpeB.js";const F=JSON.parse('{"title":"尾部风险溢价","description":"","frontmatter":{"title":"尾部风险溢价","date":"2026-09-18T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/apt-tail-risk-premia.md","filePath":"econ/apt-tail-risk-premia.md","lastUpdated":1791413859000}'),m={name:"econ/apt-tail-risk-premia.md"};function d(D,E,c,h,u,C){const A=s("Mermaid");return r(),p("div",null,[E[2]||(E[2]=t('<h1 id="尾部风险溢价" tabindex="-1">尾部风险溢价 <a class="header-anchor" href="#尾部风险溢价" aria-label="Permalink to &quot;尾部风险溢价&quot;">​</a></h1><div class="epigraph"><p>平滑的样本均值看不见小概率的大跌幅，定价却看得见：核的弯曲恰恰发生在数据最稀的地方。</p><footer>—— 据 Rietz, *Journal of Monetary Economics* 1988；Barro, *QJE* 2006；Weitzman, *AER* 2007 整理</footer></div><p><a href="/econ/apt-liquidity-deep">上一课</a>把交易摩擦记进收益；本课转向分布本身。第二课的界要求 \\(\\sigma(m)/E(m)\\) 达到 0.4 上下，而第一课的扩散假设把路径剪得连续、把左尾剪平了——用平滑消费的 CRRA 去够这条界，风险厌恶就得推到不可信的高度。缺口是左尾：溢价可能不在平均日子里，而在样本里几乎没有的那些状态中。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p><a href="/econ/equity-premium-puzzle">股权溢价之谜</a>的原始表述（Mehra–Prescott 1985）基于平滑的美国消费样本：样本里没有大灾难，CRRA 只能靠极高的 \\(\\gamma\\) 同时抬高溢价并压低无风险利率，而那样<a href="/econ/risk-free-rate-puzzle">无风险利率之谜</a>又冒出来。困难是认识论的：左尾事件在样本内太稀，无条件矩几乎不携带它们的信息——历史均值方差算不出灾难溢价的份额，缺口只能靠模型外推与别的观测器（期权、跨国长面板）补。</p><p><span class="marginnote">Barro 2006 的校准口径：约四十国、上百年的面板里，人均 GDP 累计跌幅不低于 15% 的灾难，年概率约 1.7%，平均深度约 29%。把这两行装进 Lucas 树，模型第一次同时压住股权溢价与无风险利率——代价是「灾难里股票究竟跌多少」留作自由参数。</span></p><p><span class="marginnote">数字实例：年概率 1.7%、深度 29% 的灾难，对期望增长的拖累只有约 \\(0.017\\times 29\\%\\approx 0.5\\%\\)——在样本均值上几乎无痕；但灾难状态里一元消费的边际价值极高，折现权重一变，溢价就上来了。这就是「均值看不见、定价却看得见」的算术含义。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>三条路。其一，把灾难装进模型：Rietz 1988 提出小概率灾难假说，Barro 2006 用长面板校准它；<a href="/econ/lucas-tree">Lucas 树</a>里加一条「红利累计跌近三成、年概率约 2%」的左尾，核在灾难状态乘上一个大数，溢价与利率同时回到合理区间（<a href="/econ/rare-disasters">罕见灾难</a>）。其二，从期权读尾：隐含分布的左尾有价，方差风险溢价——已实现方差与隐含方差之差——为正且能预测收益（Carr–Wu 2009；Bollerslev, Tauchen and Zhou 2009）；下行贝塔把「坏年景里的贝塔」单独拿出来定价（Ang, Chen and Xing 2006）。其三，对分布本身的认知：Weitzman 2007 证明对分布参数的学习会把观测到的肥尾内生化——感知的尾部比真实尾部更肥，低利率与高溢价同时出现。</p>',9)),(r(),i(o,null,{default:B(()=>[n(A,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20SMOOTH%5B%22%E5%B9%B3%E6%BB%91%E6%B6%88%E8%B4%B9%E6%A0%B7%E6%9C%AC%3A%20%E6%97%A0%E6%9D%A1%E4%BB%B6%E7%9F%A9%E7%9C%8B%E4%B8%8D%E5%88%B0%E5%B7%A6%E5%B0%BE%22%5D%20--%3E%20GAMMA%5B%22CRRA%20%E9%9C%80%E8%A6%81%E6%9E%81%E9%AB%98%E7%9A%84%20%CE%B3%22%5D%0A%20%20GAMMA%20--%3E%20JUMP%5B%22%E5%BC%95%E5%85%A5%E5%B0%8F%E6%A6%82%E7%8E%87%E5%A4%A7%E8%B7%8C%E5%B9%85%E7%8A%B6%E6%80%81%22%5D%0A%20%20JUMP%20--%3E%20BEND%5B%22%E6%A0%B8%E5%9C%A8%E7%81%BE%E9%9A%BE%E7%8A%B6%E6%80%81%E5%BC%AF%E6%9B%B2%22%5D%0A%20%20BEND%20--%3E%20OPT%5B%22%E6%9C%9F%E6%9D%83%E9%9A%90%E5%90%AB%E5%B7%A6%E5%B0%BE%20%2F%20%E6%96%B9%E5%B7%AE%E9%A3%8E%E9%99%A9%E6%BA%A2%E4%BB%B7%E5%8F%AF%E8%A7%82%E6%B5%8B%22%5D%0A%20%20BEND%20--%3E%20PAN%5B%22%E8%B7%A8%E5%9B%BD%E9%95%BF%E9%9D%A2%E6%9D%BF%E6%A0%A1%E5%87%86%E7%81%BE%E9%9A%BE%E6%A6%82%E7%8E%87%22%5D%0A"})]),fallback:B(()=>[...E[0]||(E[0]=[a(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=e("h2",{id:"机制",tabindex:"-1"},[a("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),E[4]||(E[4]=e("p",null,[a("尾部溢价为什么不是普通的波动溢价：扩散下连续对冲成立，跳跃不可对冲——第一课给跳跃立的那笔账在这里定价，跳跃风险的补偿是对「复制断裂」的保险。无条件夏普比率主要由少数状态贡献：普通日子里收益与核几乎无关，溢价集中在灾难日前后，这就是为什么高波动时期可以有平平的已实现溢价。时变性也由此而来：灾难概率随波动与宏观条件移动（Kelly–Jiang 2014），溢价的波动是状态、不是噪声。偏好侧的另一条路——让弯曲来自习惯或长期风险（"),e("a",{href:"/econ/habit-formation"},"习惯形成"),a("、"),e("a",{href:"/econ/long-run-risk"},"长期风险"),a("）——与本课共享「弯曲在坏状态」的结构，下一课把两条路的证据义务摆在一起。")],-1)),E[5]||(E[5]=e("p",null,"上一张图画「为什么需要左尾」；这一张对比两种价格路径下对冲能否成立，说明跳跃风险的补偿为什么必须单独开价、不能混进普通波动溢价。",-1)),(r(),i(o,null,{default:B(()=>[n(A,{id:"mermaid-35",class:"mermaid",graph:"flowchart%20TD%0A%20%20MOVE%5B%22%E4%BB%B7%E6%A0%BC%E4%B8%8B%E4%B8%80%E6%AD%A5%E6%80%8E%E4%B9%88%E5%8A%A8%22%5D%20--%3E%20DIFF%5B%22%E8%BF%9E%E7%BB%AD%E6%89%A9%E6%95%A3%EF%BC%9A%E5%B0%8F%E5%B9%85%E6%BB%91%E5%8A%A8%22%5D%0A%20%20MOVE%20--%3E%20JUMP%5B%22%E8%B7%B3%E8%B7%83%EF%BC%9A%E7%9E%AC%E9%97%B4%E8%B7%B3%E7%A9%BA%22%5D%0A%20%20DIFF%20--%3E%20HEDGE%5B%22%E6%8C%81%E4%BB%93%E6%9D%A5%E5%BE%97%E5%8F%8A%E8%BF%9E%E7%BB%AD%E8%B0%83%E6%95%B4%EF%BC%9A%E5%A4%8D%E5%88%B6%E6%88%90%E7%AB%8B%22%5D%0A%20%20JUMP%20--%3E%20BREAK%5B%22%E8%B7%B3%E7%A9%BA%E6%9D%A5%E4%B8%8D%E5%8F%8A%E8%B0%83%E4%BB%93%EF%BC%9A%E5%A4%8D%E5%88%B6%E6%96%AD%E8%A3%82%22%5D%0A%20%20HEDGE%20--%3E%20P1%5B%22%E9%A3%8E%E9%99%A9%E5%8F%AF%E4%BF%9D%E9%99%A9%EF%BC%8C%E6%8C%89%E6%89%A9%E6%95%A3%E5%8F%A3%E5%BE%84%E8%AE%A1%E8%A1%A5%E5%81%BF%22%5D%0A%20%20BREAK%20--%3E%20P2%5B%22%E4%B8%8D%E5%8F%AF%E4%BF%9D%E9%99%A9%EF%BC%9A%E8%B7%B3%E8%B7%83%E9%A3%8E%E9%99%A9%E5%8D%95%E7%8B%AC%E5%BC%80%E4%BB%B7%22%5D%0A"})]),fallback:B(()=>[...E[1]||(E[1]=[a(" Loading... ",-1)])]),_:1})),E[6]||(E[6]=t('<p><span class="marginnote">术语翻译：「方差风险溢价」是期权市场为「未来波动会有多大」开的价，与后来实际兑现的波动之差。它平均为正——投资者愿意为「怕大波动」付保费——所以被当作市场尾部担忧的温度计：读数升高，往往对应灾难概率被感知得更肥。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>灾难概率与灾难中的资产收益都是自由参数：Barro 度量的是 GDP 不是消费，灾难里股票的收益结构在数据上仍难钉，校准自由度大到「界内」不等于「对」。美国样本自证循环的风险真实存在——这正是上一课程<a href="/econ/pm-specification-map">实证设计规范与收束</a>警告的那类自由度，跨国与期权数据是必须的独立观测器。还有识别的长期债务：尾部模型与行为模型（下一课）在可预测性上常常同预言，判别要靠第三类证据，不能靠拟合优度。</p><p><span class="marginnote">常见误区：把「尾部模型能拟合溢价」当成「灾难假说被证实」。灾难的概率、深度与灾难中股票的跌幅都是校准者自定的参数，美国样本还可能自证循环——拟合成功只是必要条件，跨国长面板与期权隐含分布才是独立的证据来源。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>平滑样本看不见左尾，但核的弯曲恰在小概率状态；溢价是灾难日的，不是平均日的。</li><li>灾难校准（年概率约 2%、深度近三成）能同时压住股权溢价与无风险利率，但留有自由参数。</li><li>跳跃不可对冲，尾部溢价是对复制断裂的保险；期权隐含分布与方差风险溢价是可观测对应物。</li><li>学习效应把感知尾部放大（Weitzman 2007），低利率与高溢价得以共存。</li><li>出处：Rietz 1988；Mehra and Prescott, <em>JME</em> 1985；Barro, <em>QJE</em> 2006；Weitzman, <em>AER</em> 2007；Carr and Wu, <em>RFS</em> 2009。</li></ul>',6))])}const P=l(m,[["render",d]]);export{F as __pageData,P as default};
